    /// `ScrollbarVisibility` (mezz/jei/api/gui/widgets/ScrollbarVisibility.java)
    pub mod scrollbar_visibility {
        use super::*;
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
        pub enum ScrollbarVisibility {
            Default,
            Enabled,
            AutoHide,
            Disabled,
        }
        impl ScrollbarVisibility {
            pub const VALUES: [ScrollbarVisibility; 4] = [ScrollbarVisibility::Default, ScrollbarVisibility::Enabled, ScrollbarVisibility::AutoHide, ScrollbarVisibility::Disabled, ];
            /// Java's `name()`.
            pub fn java_name(self) -> &'static str {
                match self {
                    ScrollbarVisibility::Default => "DEFAULT",
                    ScrollbarVisibility::Enabled => "ENABLED",
                    ScrollbarVisibility::AutoHide => "AUTO_HIDE",
                    ScrollbarVisibility::Disabled => "DISABLED",
                }
            }
            /// Java's `valueOf`: panics on a name that isn't one, as Java throws.
            pub fn value_of(name: &str) -> Self {
                match name {
                    "DEFAULT" => ScrollbarVisibility::Default,
                    "ENABLED" => ScrollbarVisibility::Enabled,
                    "AUTO_HIDE" => ScrollbarVisibility::AutoHide,
                    "DISABLED" => ScrollbarVisibility::Disabled,
                    _ => panic!("No enum constant {name}"),
                }
            }
        }
    }

