    /// `RecipeTransferResult` (mezz/jei/api/recipe/transfer/RecipeTransferResult.java)
    pub mod recipe_transfer_result {
        use super::*;
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
        pub enum RecipeTransferResult {
            Success,
            Rejected,
        }
        impl RecipeTransferResult {
            pub const VALUES: [RecipeTransferResult; 2] = [RecipeTransferResult::Success, RecipeTransferResult::Rejected, ];
            /// Java's `name()`.
            pub fn java_name(self) -> &'static str {
                match self {
                    RecipeTransferResult::Success => "SUCCESS",
                    RecipeTransferResult::Rejected => "REJECTED",
                }
            }
            /// Java's `valueOf`: panics on a name that isn't one, as Java throws.
            pub fn value_of(name: &str) -> Self {
                match name {
                    "SUCCESS" => RecipeTransferResult::Success,
                    "REJECTED" => RecipeTransferResult::Rejected,
                    _ => panic!("No enum constant {name}"),
                }
            }
        }
    }

