    pub mod i_edit_mode_config_hide_mode {
        use super::*;
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
        pub enum HideMode {
            Single,
            Wildcard,
        }
        impl HideMode {
            pub const VALUES: [HideMode; 2] = [HideMode::Single, HideMode::Wildcard, ];
            /// Java's `name()`.
            pub fn java_name(self) -> &'static str {
                match self {
                    HideMode::Single => "SINGLE",
                    HideMode::Wildcard => "WILDCARD",
                }
            }
            /// Java's `valueOf`: panics on a name that isn't one, as Java throws.
            pub fn value_of(name: &str) -> Self {
                match name {
                    "SINGLE" => HideMode::Single,
                    "WILDCARD" => HideMode::Wildcard,
                    _ => panic!("No enum constant {name}"),
                }
            }
        }
    }

