    /// `InputPhase` (mezz/jei/common/input/InputPhase.java)
    pub mod input_phase {
        use super::*;
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
        pub enum InputPhase {
            Press,
            Release,
        }
        impl InputPhase {
            pub const VALUES: [InputPhase; 2] = [InputPhase::Press, InputPhase::Release, ];
            /// Java's `name()`.
            pub fn java_name(self) -> &'static str {
                match self {
                    InputPhase::Press => "PRESS",
                    InputPhase::Release => "RELEASE",
                }
            }
            /// Java's `valueOf`: panics on a name that isn't one, as Java throws.
            pub fn value_of(name: &str) -> Self {
                match name {
                    "PRESS" => InputPhase::Press,
                    "RELEASE" => InputPhase::Release,
                    _ => panic!("No enum constant {name}"),
                }
            }
        }
    }

