    /// `JeiKeyModifier` (mezz/jei/common/input/keys/JeiKeyModifier.java)
    pub mod jei_key_modifier {
        use super::*;
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
        pub enum JeiKeyModifier {
            Control,
            ControlOrCommand,
            Shift,
            Alt,
            None,
        }
        impl JeiKeyModifier {
            pub const VALUES: [JeiKeyModifier; 5] = [JeiKeyModifier::Control, JeiKeyModifier::ControlOrCommand, JeiKeyModifier::Shift, JeiKeyModifier::Alt, JeiKeyModifier::None, ];
            /// Java's `name()`.
            pub fn java_name(self) -> &'static str {
                match self {
                    JeiKeyModifier::Control => "CONTROL",
                    JeiKeyModifier::ControlOrCommand => "CONTROL_OR_COMMAND",
                    JeiKeyModifier::Shift => "SHIFT",
                    JeiKeyModifier::Alt => "ALT",
                    JeiKeyModifier::None => "NONE",
                }
            }
            /// Java's `valueOf`: panics on a name that isn't one, as Java throws.
            pub fn value_of(name: &str) -> Self {
                match name {
                    "CONTROL" => JeiKeyModifier::Control,
                    "CONTROL_OR_COMMAND" => JeiKeyModifier::ControlOrCommand,
                    "SHIFT" => JeiKeyModifier::Shift,
                    "ALT" => JeiKeyModifier::Alt,
                    "NONE" => JeiKeyModifier::None,
                    _ => panic!("No enum constant {name}"),
                }
            }
        }
    }

